UPDATE opc_finance_voucher
summary = #{summary}, total_debit = #{totalDebit}, total_credit = #{totalCredit}, entries_json = #{entriesJson}, status = #{status}, reviewed_by = #{reviewedBy}, reviewed_time = #{reviewedTime}, posted_by = #{postedBy}, posted_time = #{postedTime}, update_by = #{updateBy}, update_time = NOW()
WHERE id = #{id}
